SELECT FROM tb_code_group g
AND g.use_yn = #{useYn}
AND ( LOWER(g.code_group_id) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(g.code_group_name) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(COALESCE(g.description, '')) LIKE '%' || LOWER(#{keyword}) || '%' )
AND g.group_kind = #{groupKind}
ORDER BY g.code_group_id

SELECT 
  FROM tb_code_group g
 WHERE g.code_group_id = #{codeGroupId}

SELECT c.code_seq, c.code_group_seq, c.code_id, c.code_name, c.description,
       c.attr1, c.attr2, c.sort_order, c.use_yn,
       c.created_by, c.created_at, c.updated_by, c.updated_at
  FROM tb_code c
 WHERE c.code_group_seq = #{codeGroupSeq}
   AND c.code_id = #{codeId}

